<section class="record-sheet" aria-labelledby="season-compare-heading">
  <style>.ct-record .record-comparison-table{min-width:420px;font-size:.85rem}.ct-record .record-comparison-table th,.ct-record .record-comparison-table td{white-space:nowrap;overflow-wrap:normal;letter-spacing:normal;text-transform:none;padding:.5rem .35rem}.ct-record .record-comparison-table caption{white-space:normal;overflow-wrap:normal}</style>
  <h2 id="season-compare-heading">Compare seasons</h2>
  <form method="get" class="record-filter mb-3" action="<?php echo e(route('my.tennis.record', ['player' => $recordPlayer->id])); ?>">
    <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['year'] !== ''): ?><input type="hidden" name="year" value="<?php echo e($record['year']); ?>"><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
    <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = ['first' => 'Starting season', 'second' => 'Comparison season']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $side => $label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
      <div><label class="form-label" for="compare-<?php echo e($side); ?>"><?php echo e($label); ?></label><select id="compare-<?php echo e($side); ?>" class="form-select" name="compare_<?php echo e($side); ?>"><option value="">Choose a season</option>
        <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['comparison'][$side.'_year'] !== '' && !in_array($record['comparison'][$side.'_year'], array_map('strval', $record['years']), true)): ?><option value="<?php echo e($record['comparison'][$side.'_year']); ?>" selected><?php echo e($record['comparison'][$side.'_year']); ?> · no available results</option><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
        <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = $record['years']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $availableYear): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($availableYear); ?>" <?php if((string)$availableYear === $record['comparison'][$side.'_year']): echo 'selected'; endif; ?>><?php echo e($availableYear); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
      </select></div>
    <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
    <button class="btn btn-primary" type="submit">Compare seasons</button>
  </form>
  <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['comparison']['reason']): ?><p class="record-note mb-0" role="status"><?php echo e($record['comparison']['reason']); ?></p><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
  <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['comparison']['delta'] !== null): ?>
    <div class="row g-3 mb-3" aria-hidden="true">
      <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = ['played' => 'Recorded matches', 'rate' => 'Win rate']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $metric => $label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
        <?php ($maximum = $metric === 'rate' ? 100 : max($record['comparison']['first']['played'], $record['comparison']['second']['played'])); ?>
