  <div class="table-responsive" role="region" aria-label="Season comparison table; scroll horizontally on small screens" tabindex="0"><table class="table table-sm mb-0 record-comparison-table">
    <caption>Win-rate change is shown in percentage points (pp).</caption>
    <thead><tr><th scope="col">Measure</th><th scope="col"><?php echo e($record['comparison']['first_year'] ?: 'Starting'); ?></th><th scope="col"><?php echo e($record['comparison']['second_year'] ?: 'Comparison'); ?></th><th scope="col">Change</th></tr></thead>
    <tbody><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = ['played' => 'Matches', 'wins' => 'Wins', 'losses' => 'Losses', 'rate' => 'Win rate', 'events' => 'Events', 'opponents' => 'Opponents']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $metric => $label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
      <tr><th scope="row"><?php echo e($label); ?></th><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = ['first', 'second']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $side): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><td><?php echo e($record['comparison'][$side]['played'] ? ($metric === 'rate' ? $record['comparison'][$side][$metric].'%' : $record['comparison'][$side][$metric]) : '—'); ?></td><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?><td><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['comparison']['delta'] !== null): ?><?php echo e($record['comparison']['delta'][$metric] > 0 ? '+' : ''); ?><?php echo e($record['comparison']['delta'][$metric]); ?><?php echo e($metric === 'rate' ? ' pp' : ''); ?><?php else: ?>—<?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?></td></tr>
    <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?></tbody>
  </table></div>
  <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php $__currentLoopData = ['first', 'second']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $side): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if($record['comparison'][$side]['played']): ?><p class="record-note mt-2 mb-0"><?php echo e($record['comparison'][$side.'_year']); ?> recorded dates: <?php echo e($record['comparison'][$side]['from']); ?> to <?php echo e($record['comparison'][$side]['through']); ?>.</p><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?> <?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
  <?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if BLOCK]><![endif]--><?php endif; ?><?php if(($record['comparison']['first']['played'] > 0 && $record['comparison']['first']['played'] < 5) || ($record['comparison']['second']['played'] > 0 && $record['comparison']['second']['played'] < 5)): ?><p class="record-note mt-2 mb-0">Small sample · fewer than five saved matches in at least one season.</p><?php endif; ?><?php if(\Livewire\Mechanisms\ExtendBlade\ExtendBlade::isRenderingLivewireComponent()): ?><!--[if ENDBLOCK]><![endif]--><?php endif; ?>
